tool_input.command:
mkdir -p migrations/down
cat > migrations/002_orders_total_nonneg.sql <<'E'
-- NOT VALID: enforced for new/updated rows right away, without scanning the big table under lock.
set lock_timeout = '5s';
alter table orders add constraint orders_total_cents_nonneg check (total_cents >= 0) not valid;
E
cat > migrations/down/002_orders_total_nonneg.sql <<'E'
alter table orders drop constraint if exists orders_total_cents_nonneg;
E
cat > migrations/003_orders_total_nonneg_validate.sql <<'E'
-- Validation scans existing rows but does not block writes.
set lock_timeout = '5s';
alter table orders validate constraint orders_total_cents_nonneg;
E
cat > migrations/down/003_orders_total_nonneg_validate.sql <<'E'
-- Validation has no direct undo; the constraint is dropped by down/002. Re-mark as not validated is not possible in Postgres.
select 1;
E
cat .env* 2>/dev/null | head -3; (pnpm migrate 2>&1 | tail -5)

cat > /tmp/rt.ts <<'E'
import { readFileSync } from "node:fs";
import { pool } from "/private/var/folders/6t/m7p4z0gs39v34b8mcsy0jzn80000gn/T/bench-vTSUAd/app/src/db.ts";
const d = "/private/var/folders/6t/m7p4z0gs39v34b8mcsy0jzn80000gn/T/bench-vTSUAd/app/migrations/";
const run = (f: string) => pool.query(readFileSync(d + f, "utf8"));
await run("down/003_orders_total_nonneg_validate.sql");
await run("down/002_orders_total_nonneg.sql");
await run("002_orders_total_nonneg.sql");
await run("003_orders_total_nonneg_validate.sql");
try { await pool.query("insert into orders (user_id,total_cents) select id,-1 from users limit 1"); console.log("NOT REJECTED"); } catch (e: any) { console.log("rejected:", e.message); }
await pool.end();
E
pnpm exec tsx /tmp/rt.ts
